private fun onAppPause() {
    if (timerManager.isRunning) {
        wasRunningBeforePause = true
        pauseDebounceJob?.cancel()
        pauseDebounceJob = viewModelScope.launch {
            delay(3_000)
            pauseTimer()
        }
    }
}

private fun onAppResume() {
    if (wasRunningBeforePause) {
        pauseDebounceJob?.cancel()
        pauseDebounceJob = null
        if (timerManager.isPaused) {
            val task = uiState.value.tasks.find { ... }
            if (task != null) {
                viewModelScope.launch { resumeTimer(task) }
            }
        }
        wasRunningBeforePause = false
    }
}

